test('Safari copie le vrai contexte embarqué sans API ni presse-papiers moderne',async()=>{const {LEARNING_TRACKS}=await import('../worker/index.js');const page=await(await worker.fetch(new Request('https://test/'),{},{})).text(),script=page.match(/<script[^>]*>([\s\S]*)<\/script>/)[1];const prompt=script.slice(script.indexOf('const makeCoursePrompt='),script.indexOf(';const preparedPrompts='));const code=script.slice(script.indexOf('async function copyCourse('),script.indexOf('async function enrichCourse('));const fields=new Map([['#tutor-input-pentest-1',{value:'Explique --bind'}],['#copy-status-pentest-1',{}],['#copy-panel-pentest-1',{}],['#copy-preview-pentest-1',{focus(){},select(){},setSelectionRange(a,b){this.selection=[a,b];}}]]);let copies=0;const context=vm.createContext({learningTracks:LEARNING_TRACKS,preparedPrompts:new Map(),tutorDrafts:new Map(),courseResults:new Map(),tutorThreads:new Map(),$:key=>fields.get(key),navigator:{},document:{execCommand(command){assert.equal(command,'copy');copies++;return true;}}});new vm.Script(prompt+';'+code).runInContext(context);await vm.runInContext("copyCourse('pentest-1')",context);const preview=fields.get('#copy-preview-pentest-1');assert.equal(copies,1);assert.ok(preview.value.includes('MANIPULATIONS ET COMMANDES EXACTES'));assert.ok(preview.value.endsWith('Explique --bind'));assert.equal(preview.selection[1],preview.value.length);assert.equal(fields.get('#copy-panel-pentest-1').open,true);assert.match(fields.get('#copy-status-pentest-1').textContent,/copiés/);});
test('Un court post français étiqueté anglais ne consomme pas le quota de traduction',async()=>{const page=await(await worker.fetch(new Request('https://test/'),{},{})).text(),script=page.match(/<script[^>]*>([\s\S]*)<\/script>/)[1];const code=script.slice(script.indexOf('function looksFrench('),script.indexOf('function needsFrench('));const context=vm.createContext({});new vm.Script(code).runInContext(context);assert.equal(vm.runInContext("looksFrench({language:'en',title:'Comment ça va vous aujourd’hui?',summary:'Comment ça va vous aujourd’hui?'})",context),true);assert.equal(vm.runInContext("looksFrench({language:'en',title:'Une vulnérabilité dans Windows',summary:'Voici les détails pour corriger cette faille.'})",context),true);assert.equal(vm.runInContext("looksFrench({language:'en',title:'Critical Windows vulnerability',summary:'Apply this security update now.'})",context),false);});

function securityEnvironment(extra={}){const instances=new Map(),stores=new Map();const env={APP_ACCESS_TOKEN:'security-test-master-32-characters-fixture',GEMINI_API_KEY:'security-test-key',GEMINI_FREE_TIER_CONFIRMED:'true',...extra};env.SOCIAL_STORE={idFromName:name=>name,get:name=>{if(!instances.has(name)){const storage=memoryStore();stores.set(name,storage);instances.set(name,new (class {constructor(){this.object=null;}async fetch(req){if(!this.object){const {SocialStore}=await import('../worker/index.js');this.object=new SocialStore({storage},env);}return this.object.fetch(typeof req==='string'?new Request(req):req);}})());}return instances.get(name);}};return {env,stores,instances};}
test('Les sessions navigateur expirent, se révoquent et ne stockent pas le code maître',async()=>{const {authorized}=await import('../worker/index.js');const {env,stores}=securityEnvironment();const login=()=>worker.fetch(new Request('https://test/api/session',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+env.APP_ACCESS_TOKEN}}),env);const r=await login();assert.equal(r.status,200);const {token}=await r.json();assert.match(token,/^cv1\./);assert.notEqual(token,env.APP_ACCESS_TOKEN);const request=new Request('https://test/api/health',{headers:{Authorization:'Bearer '+token}});assert.equal(await authorized(request,env),true);assert.equal(await authorized(request,{...env,APP_ACCESS_TOKEN:'rotated-security-test-master-code-0001'}),false);const store=stores.get('cyberveille-security-v1');assert.ok(!JSON.stringify([...store.values]).includes(env.APP_ACCESS_TOKEN));const revoke=await worker.fetch(new Request('https://test/api/logout',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+token}}),env);assert.equal(revoke.status,200);assert.equal(await authorized(request,env),false);const second=await(await login()).json();for(const [key,row] of store.values)if(key.startsWith('session:'))row.lastSeen=Date.now()-3*3600000;assert.equal(await authorized(new Request('https://test/',{headers:{Authorization:'Bearer '+second.token}}),env),false);});
test('La connexion refuse temporairement les rafales sans verrouillage permanent',async()=>{const {env}=securityEnvironment();let r;for(let i=0;i<21;i++)r=await worker.fetch(new Request('https://test/api/session',{method:'POST',headers:{Origin:'https://test','CF-Connecting-IP':'192.0.2.1',Authorization:'Bearer incorrect'}}),env);assert.equal(r.status,429);assert.ok((await r.json()).retryAfterSeconds>0);const other=await worker.fetch(new Request('https://test/api/session',{method:'POST',headers:{Origin:'https://test','CF-Connecting-IP':'192.0.2.2',Authorization:'Bearer '+env.APP_ACCESS_TOKEN}}),env);assert.equal(other.status,200);});
test('Le corps non annoncé est coupé pendant la lecture plutôt qu’après son allocation complète',async()=>{let bytes=0,cancelled=false;const body=new ReadableStream({pull(c){if(bytes>=65536){c.close();return;}bytes+=4096;c.enqueue(new Uint8Array(4096).fill(32));},cancel(){cancelled=true;}});const r=await worker.fetch(new Request('https://test/api/course',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+'b'.repeat(32)},body,duplex:'half'}),{APP_ACCESS_TOKEN:'b'.repeat(32),GEMINI_API_KEY:'fixture',GEMINI_FREE_TIER_CONFIRMED:'true'});assert.ok([400,413].includes(r.status));assert.ok(bytes<65536);assert.equal(cancelled,true);});
test('Le script réel porte un nonce CSP aléatoire et tous les autres scripts inline sont interdits',async()=>{const one=await worker.fetch(new Request('https://test/'),{},{}),two=await worker.fetch(new Request('https://test/'),{},{});const csp=one.headers.get('Content-Security-Policy'),html=await one.text(),nonce=html.match(/<script nonce="([^"]+)"/)[1];assert.ok(csp.includes("script-src 'nonce-"+nonce+"'"));assert.ok(!/script-src[^;]*unsafe-inline/.test(csp));assert.notEqual(csp,two.headers.get('Content-Security-Policy'));assert.equal(one.headers.get('Cache-Control'),'no-store');assert.ok(one.headers.has('Permissions-Policy'));assert.ok(one.headers.has('Strict-Transport-Security'));new vm.Script(html.match(/<script[^>]*>([\s\S]*)<\/script>/)[1]);});
test('Deux instances Worker partagent la même réservation Gemini',async()=>{const a=await import('../worker/index.js?global-ai-a'),b=await import('../worker/index.js?global-ai-b');const {env}=securityEnvironment();let release,started;const ready=new Promise(r=>started=r),gate=new Promise(r=>release=r);const original=globalThis.fetch;let calls=0;globalThis.fetch=async()=>{calls++;started();await gate;return new Response(JSON.stringify({candidates:[{content:{parts:[{text:'Réponse du laboratoire.'}]}}]}));};try{const first=a.generateExplanation('gemini',env,[]);await ready;const second=await b.generateExplanation('gemini',env,[]);assert.equal(second.code,'app_rate_limit');assert.equal(calls,1);release();assert.equal((await first).text,'Réponse du laboratoire.');}finally{release();globalThis.fetch=original;}});
