test('La traduction persistée est réutilisée entre instances et conserve le bon identifiant',async()=>{const a=await import('../worker/index.js?article-translation-a'),b=await import('../worker/index.js?article-translation-b');const {env}=securityEnvironment();let calls=0;const original=globalThis.fetch;globalThis.fetch=async(url,options)=>{assert.ok(String(url).startsWith('https://generativelanguage.googleapis.com/'));calls++;const body=JSON.parse(options.body);assert.equal(body.generationConfig.responseMimeType,'application/json');return new Response(JSON.stringify({candidates:[{content:{parts:[{text:JSON.stringify({translations:[{index:0,title:'Une vulnérabilité dans Ghostscript',summary:'Le logiciel nécessite une mise à jour de sécurité.'}]})}]},finishReason:'STOP'}]}));};const request=id=>new Request('https://test/api/translate',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+env.APP_ACCESS_TOKEN},body:JSON.stringify({ids:[id],items:[{id,title:'Уязвимость в Ghostscript',summary:'Описание проблемы Ghostscript',url:'https://xakep.ru/test-translation',sourceId:'xakep',language:'ru'}]})});try{const first=await a.default.fetch(request('old-group'),env);assert.equal(first.status,200);assert.equal((await first.json()).translations[0].id,'old-group');const second=await b.default.fetch(request('new-group'),env);assert.equal(second.status,200);const value=await second.json();assert.equal(value.translations[0].id,'new-group');assert.equal(value.cached,true);assert.equal(calls,1);}finally{globalThis.fetch=original;}});
