test('Une lecture différée par un autre collecteur ne réécrit pas sa vieille copie dans le stockage partagé',async()=>{const mod=await import('../worker/index.js?feed-lease-no-stale-write');const stamp=new Date(Date.now()-120000).toISOString(),records=mod.SOURCES.filter(s=>s.enabled).map(s=>({source:s.id,status:'ok',checkedAt:stamp,articles:[{title:'Article conservé '+s.id,summary:'Texte',url:s.home,source:s.name,sourceId:s.id,score:30,date:stamp,cves:[],references:[]}]}));let writes=0;const env={SOCIAL_STORE:{idFromName:n=>n,get:()=>({fetch:async request=>{const u=new URL(typeof request==='string'?request:request.url);if(u.pathname==='/security'){const input=JSON.parse(await request.text());return new Response(JSON.stringify({ok:input.op!=='lease'}));}if(request.method==='POST'){writes++;return new Response('{"ok":true}');}return new Response(JSON.stringify(records));}})}};const original=globalThis.fetch;globalThis.fetch=async()=>{throw Error('External download forbidden');};try{const response=await mod.default.fetch(new Request('https://test/api/feed'),env,{});assert.equal(response.status,200);assert.ok((await response.json()).events.length);assert.equal(writes,0);}finally{globalThis.fetch=original;}});

