test('Toutes les leçons possèdent un montage de laboratoire contextualisé avec contrôles et remise en état',async()=>{const {LEARNING_TRACKS,buildCoursePrompt}=await import('../worker/index.js');for(const track of LEARNING_TRACKS)for(const lesson of track.lessons){const b=lesson.blueprint;assert.ok(b.topology);assert.ok(b.prerequisites.length>=2);assert.ok(b.steps.length>=6);assert.ok(b.commands.length);assert.ok(b.checks.length>=4);assert.ok(b.evidence.length>=3);assert.ok(b.cleanup.length>=3);assert.ok(b.steps.some(s=>s.text.includes(lesson.lab.setup)));const prompt=buildCoursePrompt(track,lesson,'Comment préparer ce laboratoire ?');assert.ok(prompt.includes('MONTAGE COMPLET DU LABORATOIRE'));assert.ok(prompt.includes(b.topology));assert.ok(prompt.endsWith('Comment préparer ce laboratoire ?'));}const network=LEARNING_TRACKS.find(t=>t.id==='network').lessons[0].blueprint;assert.ok(network.topology.includes('MÊME système'));const memory=LEARNING_TRACKS.find(t=>t.id==='forensic').lessons[2].blueprint;assert.ok(memory.steps.some(s=>s.text.includes('ISO')));});
