test('Actualiser peut remplacer une tentative bloquée sans attendre les flux pour lire le social',async()=>{
 const page=await(await worker.fetch(new Request('https://test/'),{},{})).text(),js=page.match(/<script[^>]*>([\s\S]*)<\/script>/)[1];
 const nodes=new Map(),requests=[],renders=[];let releaseOld,releaseNew,socialReads=0;
 const oldGate=new Promise(r=>releaseOld=r),newGate=new Promise(r=>releaseNew=r);
 const state=id=>({events:[{id,articles:[{id,url:'https://example.com/'+id,sourceId:'s'}]}],sources:[{source:'s',status:'ok'}],pendingSources:0,batchSize:4,mode:'live'});
 const ctx=vm.createContext({AbortController,feedLoading:false,sources:[{id:'s',enabled:true}],data:{events:[],sources:[],mode:'live'},view:'feed',xArticles:[],manualArticles:[],socialArticles:[],accessToken:'session',socialLoading:false,loadSocial(){socialReads++;},mergeEvents:rows=>rows.map(a=>({...a,articles:[a]})),startAutoTranslation(){},showNotice(){},requestFailure:e=>e.message,$:key=>{if(!nodes.has(key))nodes.set(key,{textContent:'',disabled:false,setAttribute(k,v){this[k]=v;}});return nodes.get(key);},render(){renders.push(ctx.data.events[0]?.id);},fetch:async(url,options)=>{requests.push({url,options});const n=requests.length;if(n===1)await oldGate;if(n===2)await newGate;return {ok:true,json:async()=>state(n===1?'stale':'fresh')};}});
 new vm.Script(js.slice(js.indexOf('async function load('),js.indexOf('function demo(){'))).runInContext(ctx);
 const first=vm.runInContext('load()',ctx);assert.equal(socialReads,1);assert.equal(nodes.get('#refresh').disabled,false);
 const second=vm.runInContext('load(true)',ctx);assert.equal(socialReads,2);assert.equal(requests[0].options.signal.aborted,true);
 releaseOld();await first;assert.equal(ctx.feedLoading,true);assert.equal(renders.length,0);assert.equal(nodes.get('#refresh')['aria-busy'],'true');
 releaseNew();await second;assert.equal(ctx.feedLoading,false);assert.equal(ctx.data.events[0].id,'fresh');assert.ok(renders.every(id=>id==='fresh'));assert.equal(nodes.get('#refresh').textContent,'↻ Actualiser');
});
test('Annuler une actualisation annule aussi le transport et un corps JSON bloqué',async()=>{
 const page=await(await worker.fetch(new Request('https://test/'),{},{})).text(),js=page.match(/<script[^>]*>([\s\S]*)<\/script>/)[1],caller=new AbortController();let transportSignal;
 const ctx=vm.createContext({caller,setTimeout,clearTimeout,AbortController,DOMException,fetch:async(url,options)=>{transportSignal=options.signal;return {headers:new Headers({'Content-Type':'application/json'}),json:()=>new Promise(()=>{})};}});
 new vm.Script(js.slice(js.indexOf('let privateEpoch='),js.indexOf('function clearPrivateSession'))).runInContext(ctx);
 const task=vm.runInContext("fetch('/api/feed?continue=1',{signal:caller.signal,timeoutMs:1000}).then(r=>r.json())",ctx);await new Promise(r=>setTimeout(r,1));caller.abort();await assert.rejects(task,e=>e.name==='AbortError');assert.equal(transportSignal.aborted,true);
});

function adminFixture(){
 const stores=new Map(),objects=new Map(),env={APP_ACCESS_TOKEN:'admin-fixture-owner-access-token'};
 env.SOCIAL_STORE={idFromName:id=>id,get:id=>({fetch:async r=>{if(!stores.has(id))stores.set(id,memoryStore());if(!objects.has(id))objects.set(id,new (await import('../worker/index.js')).SocialStore({storage:stores.get(id)},env));return objects.get(id).fetch(typeof r==='string'?new Request(r):r);}})};
 const request=(command,extra={})=>worker.fetch(new Request('https://test/api/admin',{method:command?'POST':'GET',headers:{Authorization:'Bearer '+env.APP_ACCESS_TOKEN,...(command?{Origin:'https://test','Content-Type':'application/json'}:{}),...extra.headers},...(command?{body:JSON.stringify(command)}:{})}),env,{});
 return {env,stores,objects,request};
}
